MG.mxHum={n:'ฟังเสียงดาบ',ic:'🎐',mt:'หูของดาบ',how:'เสียงหึ่งของดาบมีสองระลอก แตะตอนวงในทับวงนอกพอดี 6 ครั้ง',t:22,rw:()=>'',
 init(B2,api){let ok=0,n=0,stop=0,t=0,sp=1;
  B2.innerHTML=`<div class="tag2" id="mxHH" style="text-align:center"></div><div id="mxHB" style="position:relative;margin:10px auto 0;width:220px;height:220px;user-select:none;touch-action:none"><div style="position:absolute;left:50%;top:50%;width:150px;height:150px;margin:-75px 0 0 -75px;border-radius:50%;border:4px solid #8ab4ff"></div><div id="mxHR" style="position:absolute;left:50%;top:50%;border-radius:50%;border:4px solid #ffd36a;box-shadow:0 0 14px #ffd36a"></div><div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:44px">🗡️</div></div>`;
  const H=B2.querySelector('#mxHH'),Rg=B2.querySelector('#mxHR'),Bx=B2.querySelector('#mxHB');let r=0;const upd=()=>{H.textContent=`${L('ได้ยิน','Heard')} ${ok}/6 · ${L('แตะแล้ว','Taps')} ${n}`};upd();
  Bx.onpointerdown=e=>{e.preventDefault();if(!api.live())return;n++;if(Math.abs(r-150)<=Math.round(16*api.ez)){ok++;Rg.style.borderColor='#5aff9a';sp=1+ok*.18+rnd()*.4}else{Rg.style.borderColor='#ff5a5a'}setTimeout(()=>Rg.style.borderColor='#ffd36a',160);upd();if(ok>=6||n>=12)api.end()};
  const iv=setInterval(()=>{if(stop)return;t+=.035*sp;r=150+Math.sin(t)*95+Math.sin(t*2.7)*18;Rg.style.width=Rg.style.height=Math.max(6,r)+'px';Rg.style.margin=`${-Math.max(6,r)/2}px 0 0 ${-Math.max(6,r)/2}px`},20);
  return{sc:()=>cl(ok/6-Math.max(0,n-ok-2)*.06,0,1),stop(){stop=1;clearInterval(iv)}}}};
