MG.mxEdge={n:'อ่านคมดาบ',ic:'⚔️',mt:'ผู้เห็นดาบก่อนดาบมา',how:'ดูทิศที่คู่ต่อสู้ฟันมา แล้วปัดกลับตามลำดับ · ยาวขึ้นทีละท่า',t:30,rw:()=>'',
 init(B2,api){const syms=['↖️','⬆️','↗️','⬅️','🛡️','➡️','↙️','⬇️','↘️'];let lvl=3,best=0,stop=0;
  const run=()=>{if(stop)return;const sub={live:api.live,end:()=>{}};let seq=[];for(let i=0;i<lvl;i++)seq.push(Ri(0,8));let inp=0,ph=0;
   B2.innerHTML=`<div id="mxEM" style="text-align:center;margin:4px 0 8px;font-weight:700">${L('ดูแนวดาบ…','Watch the blade…')} (${lvl})</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">${syms.map((s,i)=>`<button class="opt" data-i="${i}" style="font-size:28px;padding:14px 0;transition:.1s">${s}</button>`).join('')}</div>`;
   const cs=[...B2.querySelectorAll('[data-i]')],M=B2.querySelector('#mxEM');const lit=(i,c)=>{cs[i].style.background=c||'';cs[i].style.transform=c?'scale(1.08)':''};
   let k=0;const sh=()=>{if(stop||!sub.live())return;if(k>=seq.length){ph=1;M.textContent=L('ปัดกลับ!','Parry!');return}lit(seq[k],'#ff8a8a');setTimeout(()=>{lit(seq[k]);k++;setTimeout(sh,Math.round(160*api.ez))},Math.round(480*api.ez))};setTimeout(sh,450);
   cs.forEach(c=>c.onclick=()=>{if(!ph||!api.live())return;const i=+c.dataset.i;if(i!==seq[inp]){lit(i,'#5a2a2a');M.textContent=L('✕ โดนฟัน','✕ Cut through');ph=0;setTimeout(()=>api.end(),500);return}lit(i,'#9affb0');setTimeout(()=>lit(i),140);inp++;if(inp>=seq.length){best=lvl;ph=0;if(lvl>=7){setTimeout(()=>api.end(),300);return}lvl++;setTimeout(run,500)}})};
  run();return{sc:()=>cl((best-2)/5,0,1),stop(){stop=1}}}};
