  const F=B2.querySelector('#mxGF'),H=B2.querySelector('#mxGH');const upd=()=>{H.textContent=`🧍 ${L('คนพร้อม','Ready')} ${'🟢'.repeat(man)}${'⚪'.repeat(3-man)} · ${L('ตีแตก','Breaches')} ${brk}/4 · ${L('กันได้','Held')} ${hold}`};upd();
